import 'dart:convert';

class IndicatorValue {
	int? id;
	int? propertyId;
	int? economicEvaluationId;
	int? indicatorId;
	double? value;
	String? indicatorName;

	IndicatorValue({
		this.id, 
		this.propertyId, 
		this.economicEvaluationId, 
		this.indicatorId, 
		this.value, 
		this.indicatorName, 
	});

	factory IndicatorValue.(Map<String, dynamic> data) {
		return IndicatorValue(
			id: data['id'] as int?,
			propertyId: data['property_id'] as int?,
			economicEvaluationId: data['economic_evaluation_id'] as int?,
			indicatorId: data['indicator_id'] as int?,
			value: (data['value'] as num?)?.toDouble(),
			indicatorName: data['indicator_name'] as String?,
		);
	}



	Map<String, dynamic> () {
		return {
			'id': id,
			'property_id': propertyId,
			'economic_evaluation_id': economicEvaluationId,
			'indicator_id': indicatorId,
			'value': value,
			'indicator_name': indicatorName,		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [IndicatorValue].
	factory IndicatorValue.fromJson(String data) {
		return IndicatorValue.(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [IndicatorValue] to a JSON string.
	String toJson() => json.encode(());
}
